const raw = $input.first().json;
let text = "";
if (raw.text) text = raw.text;
else if (raw.message) text = typeof raw.message === "string" ? raw.message : (raw.message.content || raw.message.text || "");
else if (raw.response) text = raw.response;
else text = JSON.stringify(raw);
text = text.replace(/^```(?:json)?\s*\n?/gm, "").replace(/```\s*$/gm, "").trim();
let triage;
try { triage = JSON.parse(text); } catch (e) { return [{ json: { esRelevante: false, error: "JSON invalido en triage" } }]; }
if (typeof triage.esRelevante !== "boolean") { return [{ json: { esRelevante: false, error: "Campo esRelevante no es boolean" } }]; }
if (triage.esRelevante && !["ingreso", "egreso", "transferencia"].includes(triage.tipoMovimiento)) { return [{ json: { esRelevante: false, error: "tipoMovimiento invalido" } }]; }
return [{ json: triage }];

const bandejaCorreo = $('03 - Loop por Correo').item.json;
const triage = $('07 - Parsear Triage').item.json;

return [{
  json: {
    bandejacorreoid: bandejaCorreo.bandejacorreoid,
    bandejacorreotextoinformacion: bandejaCorreo.bandejacorreotextoinformacion,
    bandejacorreoemaildestinatario: bandejaCorreo.bandejacorreoemaildestinatario,
    tipoMovimiento: triage.tipoMovimiento,
    razon: triage.justificacion || triage.razon || ''
  }
}];
